					...primary.cancellation === undefined ? {} : { cancellation: primary.cancellation },
					...primary.timeoutMs === undefined ? {} : { timeoutMs: primary.timeoutMs },
					...primary.remoteCode === undefined ? {} : { remoteCode: primary.remoteCode }
